// Actual constructor SQL at the fixed pre-import downstream revision.
export const legacyQueueSql = "CREATE TABLE IF NOT EXISTS codex_host_queue (\n        id TEXT PRIMARY KEY,\n        thread_id TEXT NOT NULL,\n        client_id TEXT NOT NULL,\n        input_json TEXT NOT NULL,\n        position INTEGER NOT NULL,\n        created_at_ms INTEGER NOT NULL,\n        updated_at_ms INTEGER NOT NULL,\n        state TEXT NOT NULL CHECK (state IN ('queued','dispatching','steering','unknown','delivered','discarded')),\n        target_turn_id TEXT,\n        paused_reason TEXT,\n        UNIQUE(thread_id, client_id)\n      ) STRICT;\n      CREATE INDEX IF NOT EXISTS codex_host_queue_order ON codex_host_queue(thread_id, position, created_at_ms);\n      CREATE INDEX IF NOT EXISTS codex_host_queue_state ON codex_host_queue(state, thread_id);";
export const legacySenderSql = "CREATE TABLE IF NOT EXISTS message_senders (\n        thread_id TEXT NOT NULL, client_message_id TEXT NOT NULL,\n        sender_json TEXT NOT NULL, accepted_at_ms INTEGER NOT NULL,\n        PRIMARY KEY(thread_id,client_message_id)\n      ) STRICT;";
export const legacyParticipantsSql = "CREATE TABLE IF NOT EXISTS ioa_message_presence (\n      thread_id TEXT NOT NULL, client_message_id TEXT NOT NULL, login_name TEXT NOT NULL,\n      PRIMARY KEY(thread_id,client_message_id)) STRICT;\n      CREATE INDEX IF NOT EXISTS ioa_presence_names ON ioa_message_presence(thread_id,login_name);\n      CREATE TABLE IF NOT EXISTS ioa_participant_state (\n      thread_id TEXT PRIMARY KEY, revision INTEGER NOT NULL) STRICT;";
export const legacyAttachmentsSql = "CREATE TABLE IF NOT EXISTS codex_message_attachments (\n        thread_id TEXT NOT NULL,\n        client_message_id TEXT NOT NULL,\n        attachment_id TEXT NOT NULL,\n        ordinal INTEGER NOT NULL,\n        ref_json TEXT NOT NULL,\n        PRIMARY KEY(thread_id, client_message_id, attachment_id)\n      ) STRICT;\n      CREATE INDEX IF NOT EXISTS codex_message_attachments_message\n        ON codex_message_attachments(thread_id, client_message_id, ordinal);";
export const legacyTasksSql = "\nCREATE TABLE tasks (\n id TEXT PRIMARY KEY, title TEXT NOT NULL CHECK(length(trim(title))>0), description TEXT NOT NULL,\n status TEXT NOT NULL CHECK(status IN ('backlog','todo','in_progress','in_review','done','canceled')),\n project_server_id TEXT, project_id TEXT, sort_order INTEGER NOT NULL,\n revision INTEGER NOT NULL CHECK(revision>0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER,\n CHECK((project_server_id IS NULL AND project_id IS NULL) OR (project_server_id IS NOT NULL AND project_id IS NOT NULL))\n) STRICT;\nCREATE TABLE task_conversations (\n task_id TEXT NOT NULL REFERENCES tasks(id), server_id TEXT NOT NULL, thread_id TEXT NOT NULL, created_at INTEGER NOT NULL,\n PRIMARY KEY(task_id,server_id,thread_id)\n) STRICT;\nCREATE INDEX tasks_by_status ON tasks(status,sort_order,id) WHERE deleted_at IS NULL;\nCREATE INDEX conversations_by_thread ON task_conversations(server_id,thread_id,task_id);\n";
export const legacySshSql = "CREATE TABLE ssh_connections (server_id TEXT PRIMARY KEY, revision INTEGER NOT NULL, config_json TEXT NOT NULL, host_key TEXT NOT NULL, credential BLOB NOT NULL) STRICT";
